import json

# TL 5x5 from input
tl = [
    [3, 3, 1, 3, 3],
    [6, 3, 3, 5, 6],
    [1, 5, 3, 3, 3],
    [5, 3, 6, 3, 0],
    [3, 3, 5, 3, 3]
]

# Test all transformations
def t_identity(g):
    result = [row[:] for row in g]
    return result

def t_transpose(g):
    result = [[g[j][i] for j in range(len(g))] for i in range(len(g))]
    return result

def t_rotate90cw(g):
    n = len(g)
    result = [[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            result[n-1-c][r] = g[r][c]
    return result

def t_rotate90ccw(g):
    n = len(g)
    result = [[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            result[c][n-1-r] = g[r][c]
    return result

def t_flip_h(g):
    return [row[::-1] for row in g]

def t_flip_v(g):
    return g[::-1]

def t_flip_d(g):
    return g[::-1][::-1]

def t_reflect_main(g):
    return t_transpose(g)

def t_reflect_anti(g):
    n = len(g)
    return [[g[n-1-c][n-1-r] for c in range(n)] for r in range(n)]

transformations = {
    "identity": t_identity,
    "transpose": t_transpose,
    "rotate90cw": t_rotate90cw,
    "rotate90ccw": t_rotate90ccw,
    "flip_h": t_flip_h,
    "flip_v": t_flip_v,
    "flip_diag": t_flip_d,
    "reflect_main": t_reflect_main,
    "reflect_anti": t_reflect_anti
}

for name, func in transformations.items():
    result = func(tl)
    print(f"=== {name} ===")
    for row in result:
        print(row)

